// === jam.js ===
export let detik = 0;
export function mulai() {
  const id = setInterval(() => {
    detik++;
    if (detik === 3) clearInterval(id);
  }, 50);
}
// === main.js ===
import { detik, mulai } from "./jam.js";
mulai();
const salinan = detik;
setTimeout(() => console.log(detik, salinan), 300);

