cards.solution:
// === antrean.js ===
export let nomor = 0;
export function ambilNomor() {
  nomor++;
  return nomor;
}
// === main.js ===
import { nomor, ambilNomor } from "./antrean.js";
ambilNomor();
ambilNomor();
console.log("Nomor terakhir:", nomor);
